function Average(x: int, y: int, z: int): int
  requires x + y + z >= 0 || (x + y + z) % 3 == 0
{
  (x + y + z) / 3
}

function Triple(x: int): int
{
  x * 3
}

function SolveQuadraticEquation(a: int, b: int, c: int): (real, real)
  requires a != 0
  requires b * b - 4 * a * c >= 0
{
  var discriminant := b * b - 4 * a * c;
  var sqrt_discriminant := Math.Sqrt(discriminant as real);
  var a_real := a as real;
  var b_real := b as real;
  ((-b_real + sqrt_discriminant) / (2.0 * a_real),
   (-b_real - sqrt_discriminant) / (2.0 * a_real))
}

method MyMethod(x: int, a: int, b: int, c: int) returns (sol1: real, sol2: real)
  requires a != 0
  requires b * b - 4 * a * c >= 0
{
  if x >= 0 {
    var new_a := a + 1;
    var new_b := b + 2;
    var new_c := c + 3;
    sol1, sol2 := SolveQuadraticEquation(new_a, new_b, new_c);
  } else {
    var new_a := a + 1 + Triple(x);
    var new_b := b + 2 + Triple(x);
    var new_c := c + 3;
    // Ensure new_a is not zero for the quadratic equation
    assume new_a != 0;
    // Ensure discriminant is non-negative
    assume new_b * new_b - 4 * new_a * new_c >= 0;
    sol1, sol2 := SolveQuadraticEquation(new_a, new_b, new_c);
  }
}
```

